import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { test } from "node:test";
import { renderAminoJson } from "@sparkdreamnft/sparkdreamjs/chain-amino";
import { buildSigningTypes } from "./signingTypes";

// Golden test for amino (Keplr+Ledger) signing. The fixture is generated by
// the chain repo's cmd/aminogolden: for every sparkdream Msg (plus the cosmos
// messages proposals wrap them in) it holds sample messages as protobuf bytes
// and the amino JSON the chain's aminojson sign mode renders for them, in
// five variants (zero value, every field set, lists empty, nested messages
// present but empty, negative integers). Regenerate it after any proto
// change (the converters themselves come from sparkdreamjs):
//
//   cd ../sparkdream && go run ./cmd/aminogolden golden > ../sparkdream-ui/src/lib/__fixtures__/amino-golden.jsonl
//
// Each case decodes the bytes, renders them through this app's AminoTypes,
// and requires the chain's JSON exactly. cosmjs then signs that JSON and
// encodes fromAmino's result as the tx body, which the chain renders: the
// body must render to the same JSON.

interface GoldenRecord {
  type_url: string;
  variant: "zero" | "full" | "empty_lists" | "present_empty" | "negatives";
  bytes: string;
  amino: unknown;
}

// Modules this app registers codecs for. Messages of other modules are never
// built here.
const SIGNED_MODULES = [
  "blog", "session", "commons", "rep", "collect", "name", "forum", "season",
  "reveal", "futarchy", "federation", "artifact", "service", "vault",
];

// Messages that are knowingly not covered, each with the reason. Keep this
// list short and specific: everything else must match the chain.
const KNOWN_GAPS: Record<string, string> = {};

function sortKeys(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(sortKeys);
  if (v && typeof v === "object") {
    return Object.fromEntries(
      Object.keys(v as Record<string, unknown>)
        .filter((k) => (v as Record<string, unknown>)[k] !== undefined)
        .sort()
        .map((k) => [k, sortKeys((v as Record<string, unknown>)[k])]),
    );
  }
  return v;
}

function isSigned(typeUrl: string): boolean {
  const m = typeUrl.match(/^\/sparkdream\.(\w+)\.v1\./);
  if (!m) return true; // the cosmos messages in the fixture are all hand-converted here
  return SIGNED_MODULES.includes(m[1]);
}

const fixture = path.join(path.dirname(new URL(import.meta.url).pathname), "__fixtures__", "amino-golden.jsonl");

test("amino converters match the chain's aminojson", async () => {
  const records: GoldenRecord[] = fs
    .readFileSync(process.env.AMINO_GOLDEN ?? fixture, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((l) => JSON.parse(l));
  const { registry, aminoTypes } = await buildSigningTypes();

  type Codec = {
    decode: (b: Uint8Array) => unknown;
    encode: (m: unknown) => { finish: () => Uint8Array };
    fromPartial: (v: unknown) => unknown;
  };
  const failures: string[] = [];
  let checked = 0;
  for (const r of records) {
    if (!isSigned(r.type_url) || KNOWN_GAPS[r.type_url]) continue;
    const label = `${r.type_url} [${r.variant}]`;
    const codec = registry.lookupType(r.type_url) as unknown as Codec | undefined;
    if (!codec) {
      failures.push(`${label}: not in the registry`);
      continue;
    }
    checked++;
    const bytes = Buffer.from(r.bytes, "hex");
    let value: unknown;
    try {
      value = codec.decode(bytes);
    } catch (e) {
      failures.push(`${label}: decode threw: ${e instanceof Error ? e.message : e}`);
      continue;
    }
    let amino: { type: string; value: unknown };
    try {
      amino = aminoTypes.toAmino({ typeUrl: r.type_url, value });
    } catch (e) {
      failures.push(`${label}: toAmino threw: ${e instanceof Error ? e.message : e}`);
      continue;
    }
    const got = JSON.stringify(sortKeys(amino));
    const want = JSON.stringify(sortKeys(r.amino));
    if (got !== want) {
      failures.push(`${label}:\n    got  ${got}\n    want ${want}`);
      continue;
    }
    try {
      const back = aminoTypes.fromAmino(amino as import("@cosmjs/amino").AminoMsg);
      const body = registry.encode({ typeUrl: back.typeUrl, value: back.value });
      const again = JSON.stringify(sortKeys(renderAminoJson(back.typeUrl, body)));
      if (back.typeUrl !== r.type_url || again !== want) {
        failures.push(`${label}: the tx body built from fromAmino renders differently\n    got  ${again}\n    want ${want}`);
      }
    } catch (e) {
      failures.push(`${label}: fromAmino threw: ${e instanceof Error ? e.message : e}`);
    }
  }
  assert.ok(checked > 0, "no golden records checked");
  assert.equal(failures.length, 0, `${failures.length} of ${checked} cases differ from the chain:\n${failures.join("\n")}`);
});
